Let $(e_U)_{U\in\Lambda}$ be a Dirac net on $G$; see \cite[Pg. 28]{D}. By the Riemann-Lebesgue Lemma \cite[Theorem 28.40]{HR},  $\widehat{e_U}\in c_0\mbox{-}\underset{\pi\in\widehat{G}}{\oplus}\mathcal{B}(\mathcal{H}_\pi).$ Then, there exists a finite set $A\subset\widehat{G}$ such that $$\|\widehat{e_U}(\pi)\|_{\mathcal{B}(\mathcal{H}_\pi)}\leq\frac{1}{2},\ \pi\in\widehat{G}\setminus A.$$

	Let $f\in K.$ We denote by $\widehat{e_U}\widehat{f}$ the pointwise product of $\widehat{e_U}$ and $\widehat{f}.$ Now, 
	\begin{align*}
		\|\widehat{f}\|_{\ell^{p'}\mbox{-}\underset{\pi\in\widehat{G}\setminus A}{\oplus}\mathcal{B}_{p'}(\mathcal{H}_\pi)}\leq&\|\widehat{f}-\widehat{e_U}\widehat{f}\|_{\ell^{p'}\mbox{-}\underset{\pi\in\widehat{G}\setminus A}{\oplus}\mathcal{B}_{p'}(\mathcal{H}_\pi)}+\|\widehat{e_U}\widehat{f}\|_{\ell^{p'}\mbox{-}\underset{\pi\in\widehat{G}\setminus A}{\oplus}\mathcal{B}_{p'}(\mathcal{H}_\pi)}\\\leq&\|\widehat{f-f*e_U}\|_{\ell^{p'}\mbox{-}\underset{\pi\in\widehat{G}\setminus A}{\oplus}\mathcal{B}_{p'}(\mathcal{H}_\pi)}+\|\widehat{f}\|_{\ell^{p'}\mbox{-}\underset{\pi\in\widehat{G}\setminus A}{\oplus}\mathcal{B}_{p'}(\mathcal{H}_\pi)}\sup_{\pi\in\widehat{G}\setminus A}\|\widehat{e_U}(\pi)\|_{\mathcal{B}(\mathcal{H}_\pi)}\\\leq&\|\widehat{f-f*e_U}\|_{\ell^{p'}\mbox{-}\underset{\pi\in\widehat{G}\setminus A}{\oplus}\mathcal{B}_{p'}(\mathcal{H}_\pi)}+\frac{1}{2}\|\widehat{f}\|_{\ell^{p'}\mbox{-}\underset{\pi\in\widehat{G}\setminus A}{\oplus}\mathcal{B}_{p'}(\mathcal{H}_\pi)}.
	\end{align*}

	Then, applying the Hausdorff-Young inequality \cite[Theorem 31.22]{HR}, we get
	\begin{align*}
		\|\widehat{f}\|_{\ell^{p'}\mbox{-}\underset{\pi\in\widehat{G}\setminus A}{\oplus}\mathcal{B}_{p'}(\mathcal{H}_\pi)}\leq&2\|\widehat{f-f*e_U}\|_{\ell^{p'}\mbox{-}\underset{\pi\in\widehat{G}}{\oplus}\mathcal{B}_{p'}(\mathcal{H}_\pi)}\\\leq&2\|f-f*e_U\|_p\\=&2\left(\int_G|f(x)-f*e_U(x)|^p\,dm_G(x)\right)^{1/p}\\=&2\left(\int_G\left|\int_G(f(x)-f(xy^{-1}))e_U(y)\,dm_G(y)\right|^p\,dm_G(x)\right)^{1/p}.
	\end{align*}
	Therefore, using the Minkowski integral inequality, we obtain
	\begin{align*}
	\|\widehat{f}\|_{\ell^{p'}\mbox{-}\underset{\pi\in\widehat{G}\setminus A}{\oplus}\mathcal{B}_{p'}(\mathcal{H}_\pi)}\leq&2\int_G\left(\int_G|f(x)-f(xy^{-1})|^p\,dm_G(x)\right)^{1/p} e_U(y)\,dm_G(y)\\\leq&2\sup_{y\in U}\left(\int_G|f(x)-f(xy^{-1})|^p\,dm_G(x)\right)^{1/p}.
	\end{align*}

	Let $\epsilon>0.$ Since $K$ is uniformly $L^p(G)$-equicontinuous, there exists an open neighbourhood $O$ of $e$ such that $$\|R_yf-f\|_p<\frac{\epsilon}{2},\ f\in K \mbox{ and } y\in O.$$ By \cite[Proposition 2.1 (b)]{F}, we get that there exists $U\in\Lambda$ such that $$\|R_yf-f\|_p<\frac{\epsilon}{2},\ f\in K \mbox{ and } y\in U.$$ Hence, 
	\begin{align*}
		\|\widehat{f}\|_{\ell^{p'}\mbox{-}\underset{\pi\in\widehat{G}\setminus A}{\oplus}\mathcal{B}_{p'}(\mathcal{H}_\pi)}<&\epsilon,\ f\in K.\qedhere
	\end{align*}

Let $\epsilon>0.$ Since $\widehat{K}$ has uniform $\ell^p\mbox{-}\underset{\pi\in\widehat{G}}{\oplus}\mathcal{B}_p(\mathcal{H}_\pi)$-decay, there exists a finite set $A\subset\widehat{G}$ such that $$\|\widehat{f}\|_{\ell^p\mbox{-}\underset{\pi\in\widehat{G}\setminus A}{\oplus}\mathcal{B}_p(\mathcal{H}_\pi)}<\frac{\epsilon}{4},\ f\in K.$$

	Let $f\in K$ and $y\in G.$ Then, applying \cite[Corollary 31.25]{HR}, we obtain 
	\begin{align*}
	\|R_yf-f\|_{p'}\leq&\|\widehat{R_yf-f}\|_{\ell^p\mbox{-}\underset{\pi\in\widehat{G}}{\oplus}\mathcal{B}_p(\mathcal{H}_\pi)}\\=&\left(\sum_{\pi\in\widehat{G}}d_\pi\|\widehat{R_yf}(\pi)-\widehat{f}(\pi)\|_{\mathcal{B}_p(\mathcal{H}_\pi)}^p\right)^{1/p}\\\leq&\left(\sum_{\pi\in A}d_\pi\|\pi(y)\widehat{f}(\pi)-\widehat{f}(\pi)\|_{\mathcal{B}_p(\mathcal{H}_\pi)}^p\right)^{1/p}\\&+\left(\sum_{\pi\in\widehat{G}\setminus A}d_\pi\|\pi(y)\widehat{f}(\pi)-\widehat{f}(\pi)\|_{\mathcal{B}_p(\mathcal{H}_\pi)}^p\right)^{1/p}\\\leq&\sup_{\pi\in A}\|\pi(y)-I_{d_\pi}\|_{\mathcal{B}(\mathcal{H}_\pi)}\left(\sum_{\pi\in A}d_\pi\|\widehat{f}(\pi)\|_{\mathcal{B}_p(\mathcal{H}_\pi)}^p\right)^{1/p}\\&+\sup_{\pi\in \widehat{G}\setminus A}\|\pi(y)-I_{d_\pi}\|_{\mathcal{B}(\mathcal{H}_\pi)}\left(\sum_{\pi\in\widehat{G}\setminus A}d_\pi\|\widehat{f}(\pi)\|_{\mathcal{B}_p(\mathcal{H}_\pi)}^p\right)^{1/p}\\\leq&M\sup_{\pi\in A}\|\pi(y)-I_{d_\pi}\|_{\mathcal{B}(\mathcal{H}_\pi)}+\frac{\epsilon}{2},
	\end{align*}
	where $M$ is a positive number such that $\left(\sum_{\pi\in A}d_\pi\|\widehat{f}(\pi)\|_{\mathcal{B}_p(\mathcal{H}_\pi)}^p\right)^{1/p}\leq M.$

	Let $\pi\in A.$ Using continuity of $\pi,$ we obtain that there exists a neighbourhood $O_\pi$ of $e$ such that $$\|\pi(y)-I_{d_\pi}\|_{\mathcal{B}(\mathcal{H}_\pi)}<\frac{\epsilon}{2M},\ y\in O_\pi.$$ Assume that $O=\cap_{\pi\in A}O_\pi.$ Then, $$\|\pi(y)-I_{d_\pi}\|_{\mathcal{B}(\mathcal{H}_\pi)}<\frac{\epsilon}{2M},\ \pi\in A \mbox{ and } y\in O.$$ Hence, \begin{align*}
		\|R_yf-f\|_{p'}<&\epsilon,\ f\in K \mbox{ and } y\in O. \qedhere
	\end{align*}

\mbox{ }
\begin{enumerate}[{\bf (i)}]
    \item Let $r\in\mathbb{R}.$ Consider the set $K=\{\frac{r}{n}\chi_G:n\in\mathbb{N}\}\subset L^2(G).$ Since $\{\frac{r}{n}:n\in\mathbb{N}\}$ is bounded and $K$ consists of only constant functions, it follows that $K$ is bounded and uniformly $L^2(G)$-equicontinuous.  Therefore, by Theorem \ref{Pego}, $K$ is precompact.

    \item Let $A$ be a finite subset of $\widehat{G}.$ Assume that $K$ is a bounded subset of the linear span of the set consisting of matrix entries \cite[Pg. 139]{F} of elements in $A.$ Since the matrix entries are bounded functions in $L^2(G),$ $K$ is bounded subset of $L^2(G).$ For $f\in K,$ using the Schur orthogonality relations \cite[Theorem 5.8]{F} we obtain that  $$\|\widehat{f}\|_{\ell^2\mbox{-}\underset{\pi\in\widehat{G}\setminus A}{\oplus}\mathcal{B}_2(\mathcal{H}_\pi)}=0.$$ Thus, $\widehat{K}$ has uniform $\ell^2\mbox{-}\underset{\pi\in\widehat{G}}{\oplus}\mathcal{B}_2(\mathcal{H}_\pi)$-decay. Hence, by Theorem \ref{Pego}, $K$ is precompact. In particular, the convex hull of the set consisting of matrix entries of elements in $A$ is precompact.

\end{enumerate}
